-- extended-db-metrics.sql — independent SQL cross-check of the DB-derived EXTENDED results (run against soar_ext_eval).
\echo === A. alerts by severity and handling (benign LOW / FP scenarios; rule ids from the ground truth) ===
select a.raw_payload->'rule'->>'id' rule, (a.raw_payload->'rule'->>'level')::int level, a.severity, a.workflow_state, a.triage_disposition,
       (select count(*) from incident_alerts ia where ia.alert_id::text = a.id::text) incident_links,
       (select string_agg(action, ',' order by created_at) from audit_logs l where l.entity_id::text = a.id::text and action like 'ALERT_%') audits
from alerts a where a.raw_payload->'rule'->>'id' in ('5715','5760','31101','31105','31103','31151','100350')
  and a.received_at between '2026-10-01 05:15' and '2026-10-01 05:23' order by a.received_at;
\echo === A. FP-03: incident, tickets, executions, approvals ===
select i.status, i.priority,
       (select count(*) from response_plans rp where rp.incident_id::text = i.id::text) tickets,
       (select string_agg(rp.status, ',') from response_plans rp where rp.incident_id::text = i.id::text) ticket_status,
       (select count(*) from step_executions se join response_plans rp on rp.id::text = se.plan_id::text where rp.incident_id::text = i.id::text) step_executions,
       (select string_agg(ap.status || '/' || ap.approval_role, ',') from approvals ap join response_plans rp on rp.id::text = ap.response_id::text where rp.incident_id::text = i.id::text) approvals
from incidents i where i.id::text = '9f660d93-87ce-4c88-bd85-b8a8043583ba';
\echo === C. ESCALATED incident ===
select v.result, v.matching_events, v.after_state->>'evidenceSource' source from verifications v where v.incident_id::text = '654d8df6-52ea-4a10-8aab-1f512ae3c939' order by v.verified_at;
select status, investigation_number from incidents where id::text = '654d8df6-52ea-4a10-8aab-1f512ae3c939';
select action, count(*) from audit_logs where (entity_id::text = '654d8df6-52ea-4a10-8aab-1f512ae3c939' or metadata::text like '%654d8df6-52ea-4a10-8aab-1f512ae3c939%') and action in ('INVESTIGATION_REOPENED','INVESTIGATION_ESCALATED','INCIDENT_ESCALATED') group by action order by action;
\echo === C. first ESC attempt (infrastructure failure, kept as a record) ===
select count(*) as verifications_of_failed_attempt from verifications where incident_id::text = '09d9d41d-e924-46b1-b225-dc04a453b531';
\echo === B. RAG arms (incident ids taken from the two run.json files) ===
select 'A_empty_corpus' arm, count(*) incidents,
  (select count(distinct r.incident_id) from recommendations r where r.status='VALIDATED' and r.incident_id::text in ('e5a306aa-a6f5-4064-9cab-76c64918bb16','6968dc6b-8b03-4ad6-8503-904c84a47718','847b4ac3-8833-48dc-beba-9da84dd1b4bd','cf8ed1c6-86ee-43e1-9fb4-7b69f4d4ae5c','4a208ad8-1c45-4bc8-887b-a2187823b3a2','320c9ef2-c414-4293-81f3-31855aa219ce','9a49fab3-7c61-4cf3-93b6-646ff76c850d','ec553647-73a2-494d-a9c7-6245267aaace','c342572b-8166-4c46-bbe4-8cd25ccb58c6')) with_validated_recommendation,
  (select count(distinct v.incident_id) from verifications v where v.result='RESOLVED' and v.incident_id::text in ('e5a306aa-a6f5-4064-9cab-76c64918bb16','6968dc6b-8b03-4ad6-8503-904c84a47718','847b4ac3-8833-48dc-beba-9da84dd1b4bd','cf8ed1c6-86ee-43e1-9fb4-7b69f4d4ae5c','4a208ad8-1c45-4bc8-887b-a2187823b3a2','320c9ef2-c414-4293-81f3-31855aa219ce','9a49fab3-7c61-4cf3-93b6-646ff76c850d','ec553647-73a2-494d-a9c7-6245267aaace','c342572b-8166-4c46-bbe4-8cd25ccb58c6')) resolved,
  (select count(*) from agent_results ar join agent_executions ae on ae.id::text=ar.agent_execution_id::text where ar.agent_name='rag' and ae.incident_id::text in ('e5a306aa-a6f5-4064-9cab-76c64918bb16','6968dc6b-8b03-4ad6-8503-904c84a47718','847b4ac3-8833-48dc-beba-9da84dd1b4bd','cf8ed1c6-86ee-43e1-9fb4-7b69f4d4ae5c','4a208ad8-1c45-4bc8-887b-a2187823b3a2','320c9ef2-c414-4293-81f3-31855aa219ce','9a49fab3-7c61-4cf3-93b6-646ff76c850d','ec553647-73a2-494d-a9c7-6245267aaace','c342572b-8166-4c46-bbe4-8cd25ccb58c6') and jsonb_array_length(ar.output->'chunks')>0) rag_results_with_documents,
  (select count(*) from agent_results ar join agent_executions ae on ae.id::text=ar.agent_execution_id::text where ar.agent_name='rag' and ae.incident_id::text in ('e5a306aa-a6f5-4064-9cab-76c64918bb16','6968dc6b-8b03-4ad6-8503-904c84a47718','847b4ac3-8833-48dc-beba-9da84dd1b4bd','cf8ed1c6-86ee-43e1-9fb4-7b69f4d4ae5c','4a208ad8-1c45-4bc8-887b-a2187823b3a2','320c9ef2-c414-4293-81f3-31855aa219ce','9a49fab3-7c61-4cf3-93b6-646ff76c850d','ec553647-73a2-494d-a9c7-6245267aaace','c342572b-8166-4c46-bbe4-8cd25ccb58c6') and ar.output->>'status'='not_found') rag_not_found
from unnest(array['e5a306aa-a6f5-4064-9cab-76c64918bb16','6968dc6b-8b03-4ad6-8503-904c84a47718','847b4ac3-8833-48dc-beba-9da84dd1b4bd','cf8ed1c6-86ee-43e1-9fb4-7b69f4d4ae5c','4a208ad8-1c45-4bc8-887b-a2187823b3a2','320c9ef2-c414-4293-81f3-31855aa219ce','9a49fab3-7c61-4cf3-93b6-646ff76c850d','ec553647-73a2-494d-a9c7-6245267aaace','c342572b-8166-4c46-bbe4-8cd25ccb58c6']) as t(id);
select 'B_runbook_corpus' arm, count(*) incidents,
  (select count(distinct r.incident_id) from recommendations r where r.status='VALIDATED' and r.incident_id::text in ('536eef5b-4d49-4f01-b4c1-b7735e2eb310','19213acc-7d66-48e9-af16-5c322ac0bcaf','2d14868c-7cd0-41dc-98ff-fae46e8e65e0','0a8984c4-2694-4f53-9345-ecaab14f533e','df5ee60f-4bad-43b0-afe0-524d7620eaea','d08e240d-a553-46bb-a76c-d479313989b4','64472667-407d-4e39-9b82-9ff700765b22','db575272-b491-40aa-9ac5-b639e3cd4c3b','5fc3c577-b124-4a86-89c2-a5d827c7425f')) with_validated_recommendation,
  (select count(distinct v.incident_id) from verifications v where v.result='RESOLVED' and v.incident_id::text in ('536eef5b-4d49-4f01-b4c1-b7735e2eb310','19213acc-7d66-48e9-af16-5c322ac0bcaf','2d14868c-7cd0-41dc-98ff-fae46e8e65e0','0a8984c4-2694-4f53-9345-ecaab14f533e','df5ee60f-4bad-43b0-afe0-524d7620eaea','d08e240d-a553-46bb-a76c-d479313989b4','64472667-407d-4e39-9b82-9ff700765b22','db575272-b491-40aa-9ac5-b639e3cd4c3b','5fc3c577-b124-4a86-89c2-a5d827c7425f')) resolved,
  (select count(*) from agent_results ar join agent_executions ae on ae.id::text=ar.agent_execution_id::text where ar.agent_name='rag' and ae.incident_id::text in ('536eef5b-4d49-4f01-b4c1-b7735e2eb310','19213acc-7d66-48e9-af16-5c322ac0bcaf','2d14868c-7cd0-41dc-98ff-fae46e8e65e0','0a8984c4-2694-4f53-9345-ecaab14f533e','df5ee60f-4bad-43b0-afe0-524d7620eaea','d08e240d-a553-46bb-a76c-d479313989b4','64472667-407d-4e39-9b82-9ff700765b22','db575272-b491-40aa-9ac5-b639e3cd4c3b','5fc3c577-b124-4a86-89c2-a5d827c7425f') and jsonb_array_length(ar.output->'chunks')>0) rag_results_with_documents,
  (select count(*) from agent_results ar join agent_executions ae on ae.id::text=ar.agent_execution_id::text where ar.agent_name='rag' and ae.incident_id::text in ('536eef5b-4d49-4f01-b4c1-b7735e2eb310','19213acc-7d66-48e9-af16-5c322ac0bcaf','2d14868c-7cd0-41dc-98ff-fae46e8e65e0','0a8984c4-2694-4f53-9345-ecaab14f533e','df5ee60f-4bad-43b0-afe0-524d7620eaea','d08e240d-a553-46bb-a76c-d479313989b4','64472667-407d-4e39-9b82-9ff700765b22','db575272-b491-40aa-9ac5-b639e3cd4c3b','5fc3c577-b124-4a86-89c2-a5d827c7425f') and ar.output->>'status'='not_found') rag_not_found
from unnest(array['536eef5b-4d49-4f01-b4c1-b7735e2eb310','19213acc-7d66-48e9-af16-5c322ac0bcaf','2d14868c-7cd0-41dc-98ff-fae46e8e65e0','0a8984c4-2694-4f53-9345-ecaab14f533e','df5ee60f-4bad-43b0-afe0-524d7620eaea','d08e240d-a553-46bb-a76c-d479313989b4','64472667-407d-4e39-9b82-9ff700765b22','db575272-b491-40aa-9ac5-b639e3cd4c3b','5fc3c577-b124-4a86-89c2-a5d827c7425f']) as t(id);
